/* plat.h: a SysEx frame out over USB that never waits: 0 sent, -2 no room now (again later), -1 no computer */
int plat_sysex_try(const uint8_t *p, uint32_t n)
{
    if (!usb.config || usb.suspended)
        return -1;
    if (SXQ - (so_w - so_r) < (n + 2u) / 3u)
        return -2;
    return ota_wire_send(p, n) ? -1 : 0;
}

static float esqrt(float x)
{
    union {
        float f;
        uint32_t u;
    } v = {x};
    float g;
    if (x <= 0)
        return 0;
    v.u = 0x1FBD1DF5u + (v.u >> 1);           /* a first guess from the exponent, then Newton */
    g = v.f;
    g = 0.5f * (g + x / g);
    g = 0.5f * (g + x / g);
    g = 0.5f * (g + x / g);
    return g;
}

static void poly3(const v3 *pts, int n, rgb_t col, int mirror, float depth, int use_depth, float alpha, int outline)
{
    item_t *it;
    int i;
    float dsum = 0;
    if (nitems >= MAXITEM || npts + n > MAXPTS)
        return;
    it = &items[nitems++];
    it->p0 = npts;
    it->n = n;
    for (i = 0; i < n; i++) {
        float d;
        proj(pts[i], mirror, &b_pts[2 * npts], &b_pts[2 * npts + 1], &d);
        dsum += d;
        npts++;
    }
    it->depth = use_depth ? depth : dsum / n;
    it->col = col;
    it->alpha = alpha;
    it->outline = (uint8_t)outline;
}

/* 1 px lines; fade: the ends fade over that many pixels (the gold hairlines) */
static void hline(float x0, float x1, int y, rgb_t c, float alpha, float fade)
{
    int x;
    for (x = (int)x0; x < (int)x1; x++) {
        float a = alpha;
        if (fade > 0) {
            float u = (x - x0 + 1) / fade, v = (x1 - x) / fade;
            a *= u < v ? (u < 1 ? u : 1) : (v < 1 ? v : 1);
        }
        blend(x, y, c, AF(a < 0 ? 0 : a));
    }
}

/* the marked rows, dithered to RGB565, to the panel */
static void flush(void)
{
    int y0 = dirty0, y1 = dirty1, y;
    dirty0 = SH;
    dirty1 = 0;
    for (y = y0; y < y1; y += 16) {
        int h = y1 - y < 16 ? y1 - y : 16, r, x;
        lcd_sync();                                   /* the last band may still be on its way */
        for (r = 0; r < h; r++) {
            const uint8_t *p = W + 3 * SW * (y + r), *b4 = BAYER4[(y + r) & 3];
            uint16_t *o = BAND + SW * r;
            for (x = 0; x < SW; x++, p += 3) {
                uint32_t b = b4[x & 3];
                uint32_t c = (uint32_t)Q5[b][p[0]] << 11 | (uint32_t)Q6[b][p[1]] << 5 | Q5[b][p[2]];
                o[x] = (uint16_t)(c >> 8 | (c & 0xFFu) << 8);   /* the panel takes it big-endian */
            }
        }
        lcd_blit(0, (uint32_t)y, SW, (uint32_t)h, BAND);
    }
}

                                                     * the key and light scan held up (the log reads and clears) */
void fm1_timer5_irq(void)
{
    static uint32_t sub, t5_prev;
    fm1_timer5_ack();
    {
        uint32_t now = fm1_ticks(), gap = (now - t5_prev) / FM1_TICKS_PER_US;
        if (t5_prev) {
            if (gap > t5_gap_max)
                t5_gap_max = gap;
            if (gap > 300u)
                t5_late++;
        }
        t5_prev = now;
    }
    fm1b_dbg.timer_irqs++;
    if (fm1b_dbg.in_audio)
        fm1b_dbg.nested++;
    fm1_input_tick();
    /* 2 kHz: all USB SIE traffic lives here. This ISR now nests into the audio render (so the key
     * matrix keeps its rhythm, below); USB shares the MIDI queues with the audio ISR, so a poll that
     * falls inside the render waits for the first tick outside it, as it did before the nesting. */
    if (sub % 5u == 0u) {
        usb_due = 1;
#if FELUCCA_UAC
        /* the USB audio stream cannot wait for the render (one packet per 1 ms frame, a render takes
         * up to ~11.6 ms): it runs nested too. It touches only EP4 (INDEX is set on every access) and
         * the consumer side of its ring, and usb_poll never runs nested, so the two never interleave */
        if (fm1b_dbg.in_audio)
            uac_service();
#endif
    }
    if (usb_due && !fm1b_dbg.in_audio) {
        usb_due = 0;
        usb_poll();
#if FM1B_TRS
        uart_midi_poll();                           /* the TRS jack: same context, same queue */
#endif
    }
#ifdef APP_TICK
    if (sub == 0u) {                                /* 1 kHz: the app's tick (a clock, a sequencer) */
        in_tick = 1;
        app_tick();
        in_tick = 0;
    }
#endif
    if (++sub == 10u)
        sub = 0;
    {
        uint32_t run = (fm1_ticks() - t5_prev) / FM1_TICKS_PER_US;
        if (run > t5_run_max)
            t5_run_max = run;
    }
    {
        static uint32_t last, acc;
        uint32_t now = fm1_ticks();
        acc += now - last;
        last = now;
        while (acc >= 1000u * FM1_TICKS_PER_US) {
            acc -= 1000u * FM1_TICKS_PER_US;
            fm1_ms++;
        }
    }
}

/* write-protect 0x01C7FD50..0x01C7FFFF (boot info, mailbox, vectors):
 * call after the last fm1_irq_attach */
static void fm1_guard_lock_top(void)
{
    fm1__dbg_unlock();
    FM1_DBG_MSG_CLR = 0xFFFFFFFFu;
    FM1_WR_LIMIT_L(2) = 0x01C7FD50u;
    FM1_WR_LIMIT_H(2) = 0x01C7FFFFu;
    FM1_C0_WR_LIMIT_EN |= 4u;
    fm1__dbg_lock();
}

/* Powered on without a cable, the SIE does not answer and usb_start leaves
 * USB off: retry once a second from the main loop so a cable plugged in
 * later still enumerates. */
static void usb_retry(uint32_t now_ms)
{
    static uint32_t t;
    if (usb.up || usb.detached || now_ms - t < 1000u)
        return;
    t = now_ms;
    usb.retries++;
    usb_start();
}

static void usb_detach(void)
{
    usb.detached = 1;
    usb.up = 0;
    fm1_usb_off();
}

/* constant-power pan of key k (0..87) at the width */
static void pan_of(int k, int32_t *pl, int32_t *pr)
{
    int32_t p = 16384 + (((st.width * 13107) >> 15) * (k * 2 - 87)) / 87;   /* 0.5 +- 0.4 x width */
    *pr = sinq(p);
    *pl = sinq(32767 - p);
}
